  -- 0. Kiểm tra trước khi nạp
  if to_regclass('public.lich_bai') is null or to_regclass('public.student_errors') is null then
    raise exception E'

>>> Chưa chạy 42-soat-loi-va-on-ngat-quang.sql và 43-lich-giao-bai.sql. Chạy hai tệp đó trước. <<<
';
  end if;
  select count(*) into v_thieu from questions where question_id in ('C1-B1-M1-Q01', 'C1-B1-M2-Q06', 'C1-B2-M1-Q03', 'C1-B2-M2-Q08', 'C1-B3-M1B-Q05', 'C2-B4-M1-Q02', 'C2-B4-M2-Q07', 'C2-B5-M2-Q04', 'C2-B6-M2-Q01', 'C3-B10-M1-Q06', 'C3-B7-M1-Q03', 'C3-B7-M2-Q08', 'C3-B8-M2-Q05', 'C3-B9-M1B-Q02', 'C3-B9-M2-Q07', 'C3-B9-M3-Q04');
